<script setup>
import {Sun,Cloud,CloudRain,Layers,Plus} from 'lucide-vue-next';
import Control from './Control.vue';
import {sitePath} from '../../paths.js';
import {skyPresets,texturePresets} from '../scene/environment-config.js';
defineProps({modelValue:Object});const emit=defineEmits(['change','ground']);
const icons={none:Layers,sunny:Sun,overcast:Cloud,rainy:CloudRain};
</script>
<template><div class="ase-environment-panel"><div class="ase-library-intro"><span>LIGHT & LANDSCAPE</span><h2>为空间，添一层真实。</h2><p>天空、光照与地面，融入已有场景。</p></div>
 <section class="ase-environment-section"><h3>天空环境 <small>360° PANORAMA</small></h3><div class="ase-sky-grid"><button v-for="s in skyPresets" :key="s.id" :aria-label="'天空环境 '+s.name" :aria-pressed="modelValue.sky===s.id" :class="{active:modelValue.sky===s.id}" @click="modelValue.sky=s.id;emit('change')"><div :class="{'sky-transparent':s.id==='none'}"><img v-if="s.url" :src="sitePath(s.url.replace('.webp','-thumb.webp'))" alt="" loading="lazy"/><component :is="icons[s.id]" :size="18"/></div><strong>{{s.name}}</strong><small>{{s.subtitle}}</small></button></div>
 <template v-if="modelValue.sky!=='none'"><Control v-model="modelValue.brightness" label="天空亮度" type="range" :min=".2" :max="2" :step=".05" @commit="emit('change')"/><Control v-model="modelValue.rotation" label="天空朝向" type="range" :min="-180" :max="180" unit="°" @commit="emit('change')"/><Control v-model="modelValue.blur" label="背景柔化" type="range" :min="0" :max=".6" :step=".02" @commit="emit('change')"/></template>
 <Control :model-value="modelValue.fog*1000" label="空间雾感" type="range" :min="0" :max="15" :step=".5" @update:model-value="modelValue.fog=$event/1000" @commit="emit('change')"/><Control v-if="modelValue.sky==='rainy'" v-model="modelValue.rain" label="雨幕密度" type="range" :min="0" :max="1" :step=".05" @commit="emit('change')"/><p class="ase-field-note">天空同时参与环境反射。雨幕随场景播放与暂停，调整环境不重建原场景。</p></section>
 <section class="ase-environment-section"><h3>地面与铺装 <small>EDITABLE GROUND</small></h3><div class="ase-ground-grid"><button v-for="t in texturePresets.filter(t=>['concrete','grass','tile','wood'].includes(t.id))" :key="t.id" :aria-label="'添加'+t.name+'地面'" @click="emit('ground',t.id)"><img :src="sitePath(t.url)" alt="" loading="lazy"/><span>{{t.name}}<Plus :size="12"/></span></button></div><p class="ase-field-note">加入可选中、移动、缩放的地面模型；在右侧调整贴图重复、方向和材质。原有建筑与对象保持不变。</p></section>
 <section class="ase-environment-tip"><Layers :size="16"/><div><strong>环境素材，就在模型库</strong><p>远山、岩石、草丛、人物与车辆，可与场景自由组合。</p></div></section>
</div></template>
<style>
.ase-environment-panel{padding:0 16px 26px}.ase-environment-panel .ase-library-intro{padding-left:0;padding-right:0}.ase-environment-section{padding:0 0 22px;margin-bottom:20px;border-bottom:1px solid #e8eef1}.ase-environment-section h3{display:flex;align-items:center;justify-content:space-between;font-size:11px;font-weight:500;color:#4c6571;margin:0 0 13px}.ase-environment-section h3 small{font:7px monospace;letter-spacing:.6px;color:#95a5ad}.ase-sky-grid,.ase-ground-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:16px}.ase-sky-grid>button{padding:0 0 10px;text-align:left;background:#f8fafb;border:1px solid #e3e9ed;border-radius:7px;overflow:hidden;color:#4f6673;cursor:pointer}.ase-sky-grid>button.active{border-color:#72a696;background:#f0f7f3;box-shadow:0 0 0 1px #72a69618}.ase-sky-grid>button>div{position:relative;height:61px;margin-bottom:9px;overflow:hidden}.ase-sky-grid img{width:100%;height:100%;object-fit:cover}.ase-sky-grid svg{position:absolute;left:10px;top:10px;color:#f1f8ff;filter:drop-shadow(0 1px 3px #0007)}.ase-sky-grid strong,.ase-sky-grid small{display:block;margin:0 9px}.ase-sky-grid strong{font-size:10px;font-weight:500}.ase-sky-grid small{font-size:8px;color:#8c9da7;margin-top:5px}.sky-transparent{background:radial-gradient(ellipse at center,#36576d,#142535)}.ase-ground-grid>button{position:relative;border:1px solid #a8c1d426;border-radius:6px;overflow:hidden;padding:0;cursor:pointer;color:#d7e4ed;text-align:left}.ase-ground-grid img{width:100%;height:69px;object-fit:cover;display:block;transition:transform .2s}.ase-ground-grid button:hover img{transform:scale(1.05)}.ase-ground-grid button>span{position:absolute;inset:auto 0 0;display:flex;justify-content:space-between;align-items:center;background:linear-gradient(transparent,#0e1e2be8);padding:15px 8px 7px;font-size:10px}.ase-environment-tip{display:flex;gap:10px;padding:12px;background:#f4f8f7;border-radius:7px;border:1px solid #e3ede8;color:#6d9384}.ase-environment-tip strong{font-size:10px;font-weight:450}.ase-environment-tip p{font-size:9px;line-height:1.8;color:#8d9f99;margin:5px 0 0}
</style>
